/**
 * Seed the database with a realistic-looking catalog so the site is browsable
 * before any live ingestion runs.
 *
 * The figures, manufacturers and series here are real products; the *prices* are
 * synthetic — generated by a seeded random walk so charts have something to draw.
 * Once the eBay/AmiAmi jobs run, real snapshots accumulate alongside these.
 *
 * Run with: npm run db:seed   (safe to re-run — everything upserts)
 */
import "dotenv/config";
