const JPY_TO_USD = 0.0066;
const HISTORY_DAYS = 240;
const CONDITIONS = ["NEW_SEALED", "USED_COMPLETE"] as const;

/** Midnight UTC, `daysAgo` days before today. */
function dayUtc(daysAgo: number): Date {
  const now = new Date();
  const d = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate()));
  d.setUTCDate(d.getUTCDate() - daysAgo);
  return d;
}

/**
 * Synthetic price history is opt-in.
 *
 * It exists so the charts have something to draw during development. It must
 * never reach a public database: fabricated prices presented as a price
 * reference are a lie to anyone reading them, and an instant rejection from any
 * marketplace or retailer reviewing the site.
 */
const DEMO_PRICES = process.argv.includes("--demo-prices");

async function main() {
  if (DEMO_PRICES) {
    console.log("Seeding catalogue WITH SYNTHETIC PRICES (--demo-prices).");
    console.log("Local development only. Never run this against a public database.\n");
  } else {
    console.log("Seeding catalogue only — no prices.");
    console.log("Price history comes from real ingestion and community reports.\n");
  }

  // --- Sources ------------------------------------------------------------
  const sources = [
    { key: "ebay", name: "eBay", homepage: "https://www.ebay.com" },
    { key: "amiami", name: "AmiAmi", homepage: "https://www.amiami.com" },
    { key: "hlj", name: "HobbyLink Japan", homepage: "https://www.hlj.com" },
    { key: "user", name: "Community reported", homepage: null },
  ];
  for (const s of sources) {
    await prisma.source.upsert({
      where: { key: s.key },
      update: { name: s.name, homepage: s.homepage },
      create: s,
    });
  }
  const ebay = await prisma.source.findUniqueOrThrow({ where: { key: "ebay" } });

  // --- Manufacturers & series --------------------------------------------
  const manufacturerIds = new Map<string, string>();
  for (const m of MANUFACTURERS) {
    const row = await prisma.manufacturer.upsert({
      where: { name: m.name },
      update: { websiteUrl: m.websiteUrl },
      create: { name: m.name, slug: slugify(m.name), websiteUrl: m.websiteUrl },
    });
    manufacturerIds.set(m.name, row.id);
  }

  const seriesIds = new Map<string, string>();
  for (const name of SERIES) {
    const row = await prisma.series.upsert({
      where: { name },
      update: {},
      create: { name, slug: slugify(name) },
    });
    seriesIds.set(name, row.id);
  }

  // --- Figures ------------------------------------------------------------
  let figureIndex = 0;
  for (const f of FIGURES) {
    figureIndex += 1;
    const seriesId = seriesIds.get(f.series)!;
    const manufacturerId = manufacturerIds.get(f.manufacturer)!;

    const character = await prisma.character.upsert({
      where: { name_seriesId: { name: f.character, seriesId } },
      update: {},
      create: {
        name: f.character,
        slug: slugify(`${f.character}-${f.series}`),
        seriesId,
      },
    });

    const slug = slugify(`${f.name}-${f.manufacturer}`);
    // Day 15 is a placeholder within a known month; only the month is claimed.
    const releaseDate =
      f.releaseYear && f.releaseMonth
        ? new Date(Date.UTC(f.releaseYear, f.releaseMonth - 1, 15))
        : null;

    const figure = await prisma.figure.upsert({
      where: { slug },
      update: {},
      create: {
        slug,
        name: f.name,
        category: f.category,
        status: f.status ?? "RELEASED",
        scale: f.scale ?? null,
        heightMm: f.heightMm ?? null,
        releaseDate,
        // Both or neither — an amount without its currency is meaningless.
        msrpAmount: f.msrpJpy ?? null,
        msrpCurrency: f.msrpJpy ? "JPY" : null,
        manufacturerId,
        seriesId,
        characters: { connect: { id: character.id } },
        description: `${f.name} by ${f.manufacturer}, from ${f.series}.`,
      },
    });

    // A barcode identifies a product exactly, where a title match only guesses.
    // Worth storing wherever it's known, ready for matching to use.
    if (f.jan) {
      await prisma.figureIdentifier.upsert({
        where: { kind_value: { kind: "JAN", value: f.jan } },
        update: { figureId: figure.id },
        create: { figureId: figure.id, kind: "JAN", value: f.jan },
      });
    }

    // Synthetic history needs parameters that only the original demo entries
    // carry. Figures added from real evidence have none, and must not be given
    // invented ones.
    if (!DEMO_PRICES || f.marketUsd === undefined) {
      console.log(`  ${figure.name}`);
      continue;
    }

    // --- Synthetic price history ----------------------------------------
    // Only with --demo-prices. Walk backwards from today's known market value
    // so the newest point is exactly `marketUsd`, then let drift + noise
    // generate the past.
    const rng = makeRng(0x5eed + figureIndex * 7919);
    const dailyDrift = (f.drift ?? 0) / 365;

    const seriesByDay: number[] = new Array(HISTORY_DAYS);
    let value = f.marketUsd!;
    for (let i = 0; i < HISTORY_DAYS; i++) {
      seriesByDay[HISTORY_DAYS - 1 - i] = value;
      const shock = (rng() - 0.5) * 2 * (f.volatility ?? 0);
      value = value / (1 + dailyDrift + shock);
      value = Math.max(value, (f.msrpJpy ?? 0) * JPY_TO_USD * 0.5);
    }

    const snapshotRows: {
      figureId: string;
      condition: (typeof CONDITIONS)[number];
      date: Date;
      minUsd: number;
      medianUsd: number;
      avgUsd: number;
      maxUsd: number;
      sampleSize: number;
      lowestAskUsd: number;
    }[] = [];
    const saleRows: {
      sourceId: string;
      figureId: string;
      externalId: string;
      condition: (typeof CONDITIONS)[number];
      amount: number;
      currency: string;
      amountUsd: number;
      fxRate: number;
      soldAt: Date;
    }[] = [];

    for (let i = 0; i < HISTORY_DAYS; i++) {
      const daysAgo = HISTORY_DAYS - 1 - i;
      const date = dayUtc(daysAgo);
      const base = seriesByDay[i];

      for (const condition of CONDITIONS) {
        // Used copies trade at a discount to sealed.
        const conditionFactor = condition === "NEW_SEALED" ? 1 : 0.72;
        // Not every figure sells every day; rarer/pricier ones sell less often.
        const dailySales = Math.floor(rng() * (base > 300 ? 2.2 : 4.0));
        if (dailySales === 0) continue;

        const prices: number[] = [];
        for (let k = 0; k < dailySales; k++) {
          const spread = 1 + (rng() - 0.5) * 0.18;
          const price = Math.round(base * conditionFactor * spread * 100) / 100;
          prices.push(price);

          saleRows.push({
            sourceId: ebay.id,
            figureId: figure.id,
            externalId: `seed-${figure.id}-${condition}-${daysAgo}-${k}`,
            condition,
            amount: price,
            currency: "USD",
            amountUsd: price,
            fxRate: 1,
            soldAt: new Date(date.getTime() + 1000 * 60 * 60 * (8 + k)),
          });
        }

        snapshotRows.push({
          figureId: figure.id,
          condition,
          date,
          minUsd: Math.min(...prices),
          medianUsd: Math.round(median(prices) * 100) / 100,
          avgUsd: Math.round((prices.reduce((a, b) => a + b, 0) / prices.length) * 100) / 100,
          maxUsd: Math.max(...prices),
          sampleSize: prices.length,
          // Asking prices sit above realized prices.
          lowestAskUsd: Math.round(Math.min(...prices) * 1.12 * 100) / 100,
        });
      }
    }

    await prisma.priceSnapshot.deleteMany({ where: { figureId: figure.id } });
    await prisma.priceSnapshot.createMany({ data: snapshotRows });
    await prisma.sale.deleteMany({ where: { figureId: figure.id, source: { key: "ebay" } } });
    await prisma.sale.createMany({ data: saleRows, skipDuplicates: true });

    // A handful of live listings, priced a little above market.
    await prisma.listing.deleteMany({ where: { figureId: figure.id } });
    const listingCount = 2 + Math.floor(rng() * 4);
    await prisma.listing.createMany({
      data: Array.from({ length: listingCount }, (_, k) => {
        const markup = 1.05 + rng() * 0.35;
        const price = Math.round(f.marketUsd! * markup * 100) / 100;
        return {
          sourceId: ebay.id,
          figureId: figure.id,
          externalId: `seed-listing-${figure.id}-${k}`,
          title: `${f.name} ${f.manufacturer} ${k % 2 === 0 ? "US Seller" : "From Japan"}`,
          url: "https://www.ebay.com/",
          condition: (k % 3 === 0 ? "USED_COMPLETE" : "NEW_SEALED") as (typeof CONDITIONS)[number],
          amount: price,
          currency: "USD",
          amountUsd: price,
          fxRate: 1,
          shippingUsd: k % 2 === 0 ? 12.5 : 34.0,
          matchScore: 0.95,
        };
      }),
    });

    console.log(`  ${figure.name} — ${snapshotRows.length} snapshots, ${saleRows.length} sales`);
  }

  console.log("Aggregating figure stats…");
  await recomputeFigureStats();

  // Without this a freshly seeded database has an empty search index, and
  // nothing is findable until the nightly job runs.
  const indexed = await rebuildAllSearchText();
  console.log(`Search text built for ${indexed} figures.`);
  console.log("Done.");
}

main()
  .catch((e) => {
    console.error(e);
    process.exit(1);
  })
  .finally(() => prisma.$disconnect());
